//! Raw FFI bindings to Wireshark's packet dissection library.
//!
//! Generated by `bindgen` from the headers of the Wireshark installation found at build time.
//! Nothing here is safe to call: see the [`epan`](../epan/index.html) crate for the wrapper the
//! dissector actually uses.
//!
//! The bindings are regenerated on every build rather than vendored, because a plugin only loads
//! into the exact Wireshark minor version it was built against ([`WIRESHARK_VERSION_MAJOR`] /
//! [`WIRESHARK_VERSION_MINOR`]) — a checked-in copy would be wrong for every other version and
//! right for one.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(clippy::all)]
#![allow(rustdoc::all)]
// Emitted by bindgen's own accessor boilerplate, not by anything written here.
#![allow(unsafe_op_in_unsafe_fn)]
#![allow(unnecessary_transmutes)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

mod version {
    include!(concat!(env!("OUT_DIR"), "/version.rs"));
}

pub use version::{WIRESHARK_VERSION, WIRESHARK_VERSION_MAJOR, WIRESHARK_VERSION_MINOR};

// The `printf`-style entry points (`proto_item_append_text`, `col_add_fstr`, ...) are generated
// by bindgen as Rust variadics. The only safe way to hand them runtime text is as an argument to
// a literal `c"%s"` format — `epan::text` does that; nothing else should call them directly.
